args.command:
cd /workspace/dataset && python3 << 'EOF'
import struct, zlib, marshal, dis, types

data = open('test4_executable','rb').read()
MAGIC = b'MEI\x0c\x0b\x0a\x0b\x0e'
cpos = data.rfind(MAGIC)
magic, pkglen, toc_off, toc_len, pyvers, pylib = struct.unpack('!8sIIii64s', data[cpos:cpos+88])
pkg_start = cpos + 88 - pkglen
pos = pkg_start + toc_off
end = pos + toc_len
pyz = None
while pos < end:
    esize, off, clen, ulen, cflag, tcode = struct.unpack('!iIIIBB', data[pos:pos+18])
    name = data[pos+18:pos+esize].split(b'\0')[0].decode('utf-8','replace')
    if chr(tcode) == 'z':
        pyz = data[pkg_start+off: pkg_start+off+clen]
    pos += esize
toc = marshal.loads(pyz[struct.unpack('!i', pyz[8:12])[0]:])
mods = {}
for name, (typ, p, l) in toc:
    if name.startswith('sqlparse'):
        mods[name] = marshal.loads(zlib.decompress(pyz[p:p+l]))

# search all code objects for interesting names/consts
hits = []
def walk(code, mod, path):
    for n in code.co_names:
        if any(k in n.lower() for k in ('strip','whitespace','newline','rstrip','lstrip')):
            hits.append((mod, path, 'name', n))
    for c in code.co_consts:
        if isinstance(c, str) and any(k in c for k in ('\\r','\\t','\\n','strip')):
            hits.append((mod, path, 'const', repr(c)))
        elif isinstance(c, types.CodeType):
            walk(c, mod, path + '/' + c.co_name)
for m, code in mods.items():
    walk(code, m, code.co_name)
for h in hits:
    print(h)
EOF

